<div class="lead-grid">@if(auth()->user()->isAdmin())<label>Assign to *<select name="assigned_to" required>@foreach(($owners ?? collect())->filter(fn($u)=>$u->allows('leads.tasks') || $u->allows('leads.followups') || $u->allows('leads.reminders')) as $owner)<option value="{{ $owner->id }}" @selected(($work->assigned_to ?? $lead->owner_id ?? auth()->id())===$owner->id)>{{ $owner->name }}</option>@endforeach</select></label>@endif <label>Type<select name="kind">@foreach(['Task','Follow-up','Reminder'] as $kind)<option @selected(($work->kind ?? 'Follow-up')===$kind)>{{ $kind }}</option>@endforeach</select></label><label>Title *<input name="title" required maxlength="255" value="{{ $work->title ?? '' }}"></label><label>Due date & time (IST) *<input type="datetime-local" name="due_at" required value="{{ isset($work) ? $work->due_at->format('Y-m-d\TH:i') : '' }}"></label><label>Priority<select name="priority">@foreach(['Low','Normal','High'] as $priority)<option @selected(($work->priority ?? 'Normal')===$priority)>{{ $priority }}</option>@endforeach</select></label><label>Recurrence<select name="recurrence_type"><option value="">Does not repeat</option>@foreach(['Daily','Weekly','Monthly'] as $repeat)<option value="{{ $repeat }}" @selected(($work->recurrence_type ?? '')===$repeat)>{{ $repeat }}</option>@endforeach</select><input type="hidden" name="recurring" value="{{ !empty($work?->recurring) ? '1' : '0' }}"></label></div><label>Notes<textarea name="notes" rows="2" maxlength="10000">{{ $work->notes ?? '' }}</textarea></label><label>Attachment (optional)<input type="file" name="attachment" accept=".jpg,.jpeg,.png,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt">@if(!empty($work?->attachment_name))<small>Current: {{ $work->attachment_name }}</small>@endif</label>
